const education = [
  {title:"Cannabis affects everyone differently", body:"Use this app to compare wellness directions, not to diagnose, treat, cure, or prevent any condition."},
  {title:"Start low and compare slowly", body:"Lower-THC and CBD-forward options may be worth comparing first if you are sensitive or newer to cannabis."},
  {title:"Terpenes are part of the profile", body:"Terpenes like myrcene, limonene, pinene, and caryophyllene are commonly discussed with aroma and effect-style notes."},
  {title:"Safety first", body:"Follow local laws, ask for lab-tested products, talk to a licensed professional, and do not drive while impaired."}
];

const $ = (id) => document.getElementById(id);
const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));
const store = (key, value) => localStorage.setItem(key, JSON.stringify(value));
const read = (key, fallback) => { try { const value = JSON.parse(localStorage.getItem(key)); return value ?? fallback; } catch { return fallback; } };
const safeName = (v) => String(v || '').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const normalize = (v) => String(v || '').toLowerCase();
const getStrain = (name) => strains.find(s => normalize(s.name) === normalize(name));
window.$ = $; window.renderSearch = () => renderSearch();

function strainColor(s){
  const c = normalize(s?.category || s?.type);
  if(c.includes('sleep')) return '#9b88ff';
  if(c.includes('focus')) return '#62d4ff';
  if(c.includes('mood')) return '#ff7ac8';
  if(c.includes('cbd')) return '#69f7b0';
  if(c.includes('stress')) return '#45e4c8';
  if(c.includes('body')) return '#d0fb72';
  if(c.includes('appetite')) return '#ffd166';
  return '#74ffad';
}
function hexToRgb(hex){ const n=parseInt(String(hex).replace('#',''),16); return `${(n>>16)&255},${(n>>8)&255},${n&255}`; }
function cardStyle(s){ const c=strainColor(s); return `--strain-accent:${c};--accent-rgb:${hexToRgb(c)}`; }
function strainImage(s){ return s?.image || `https://images.unsplash.com/photo-1603909223429-69bb7101f420?auto=format&fit=crop&w=900&q=70&sig=${encodeURIComponent(s?.name||'strain')}`; }
function repairStrainImage(img, name){ img.onerror=null; img.src=`https://images.unsplash.com/photo-1603909223429-69bb7101f420?auto=format&fit=crop&w=900&q=70&sig=${encodeURIComponent(name||'strain')}`; }
function shortInsight(s){
  const terp = (s.terpenes || [])[0] || 'terpene';
  const tag = (s.tags || []).slice(0,2).join(' + ') || s.category || 'balanced';
  return `${s.category || 'Wellness'} direction • ${tag} • ${terp} led.`;
}
function matchSummary(s){ return `${s.name} is associated with ${(s.tags||[]).slice(0,3).join(', ').toLowerCase() || 'balanced'} educational directions. Cannabis affects everyone differently.`; }
function dailyShuffle(list, salt='daily'){
  const day = Math.floor(Date.now()/86400000);
  let seed = 0; String(salt+day).split('').forEach(ch=>seed=(seed*31+ch.charCodeAt(0))>>>0);
  return [...list].sort((a,b)=>((seed + a.name.length*17 + a.name.charCodeAt(0))%997)-((seed + b.name.length*17 + b.name.charCodeAt(0))%997));
}
function savedRecords(){ return read('srSaved', []); }
function journalRecords(){ return read('srJournal', []); }
function recentRecords(){ return read('srRecent', []); }

function setActiveNav(id){
  $$('.page').forEach(p=>p.classList.toggle('active', p.id===id));
  const order=['home','search','recommend','saved','learn'];
  $$('.nav-btn').forEach((b,i)=>b.classList.toggle('active', order[i]===id));
}
function showPage(id){
  document.body.classList.remove('modal-open');
  $('strainModal')?.classList.add('hidden');
  setActiveNav(id);
  if(id==='search') renderSearch();
  if(id==='saved') renderSaved();
  if(id==='learn') renderEducation();
  if(id==='home') renderHomeDynamic();
  requestAnimationFrame(()=>window.scrollTo({top:0, behavior:'auto'}));
}
window.showPage = showPage;

function cardHTML(s, compact=false){
  return `<article class="strain-card" style="${cardStyle(s)}" onclick="openModal('${safeName(s.name)}')">
    <div class="card-hero"><img src="${strainImage(s)}" alt="${s.name} strain image" loading="lazy" onerror="repairStrainImage(this,'${safeName(s.name)}')"><span>${s.category || 'Profile'}</span></div>
    <div class="card-meta"><b>${s.type || 'Hybrid direction'}</b><i></i></div>
    <h3>${s.name}</h3>
    <p>${compact ? shortInsight(s) : matchSummary(s)}</p>
    <div class="tags">${(s.tags||[]).slice(0, compact?3:4).map(t=>`<span class="tag">${t}</span>`).join('')}</div>
  </article>`;
}

function dailyTip(){
  const pick = dailyShuffle(strains, 'daily-wellness')[0];
  $('dailyTitle').textContent = `Terpene spotlight: ${pick.name}`;
  $('dailyText').innerHTML = `A terpene-led direction for today’s quick exploration. <strong>Spotlight:</strong> ${(pick.terpenes||['terpenes'])[0]}. <button class="inline-link" onclick="openModal('${safeName(pick.name)}')">Open profile</button>`;
}
function renderFeatured(){
  const trending = dailyShuffle(strains, 'trending').slice(0,8);
  const box = $('trendingGrid');
  if(box) box.innerHTML = trending.map(s=>cardHTML(s,true)).join('');
}
function renderSpotlight(){
  let spot = $('v91Spotlight');
  const home = $('home');
  if(!spot && home){
    spot = document.createElement('section');
    spot.id = 'v91Spotlight';
    spot.className = 'spotlight-card card-glow';
    const quick = home.querySelector('.quick-row');
    quick?.insertAdjacentElement('beforebegin', spot);
  }
  if(!spot) return;
  const s = dailyShuffle(strains, 'spotlight')[0];
  spot.style.cssText = cardStyle(s);
  spot.innerHTML = `<div class="spotlight-copy"><span class="eyebrow">Today’s Spotlight</span><h2>${s.name}</h2><p>${s.name} is associated with ${(s.tags||[]).slice(0,2).join(', ').toLowerCase()} directions and a ${((s.terpenes||[])[0]||'terpene').toLowerCase()}-forward profile for comparison.</p><button onclick="openModal('${safeName(s.name)}')">Open profile</button></div><div class="spotlight-media"><img src="${strainImage(s)}" alt="${s.name}" onerror="repairStrainImage(this,'${safeName(s.name)}')"><span>${s.category}</span></div>`;
}
function updateStats(){
  $('strainCount') && ($('strainCount').textContent = strains.length);
  $('savedCount') && ($('savedCount').textContent = savedRecords().length);
  $('journalCount') && ($('journalCount').textContent = journalRecords().length);
}
function renderLiveDashboard(){
  const home = $('home'); if(!home) return;
  let board = $('livelyDashboard');
  if(!board){
    board = document.createElement('section'); board.id='livelyDashboard'; board.className='panel card-glow lively-dashboard';
    home.querySelector('.pro-card')?.insertAdjacentElement('afterend', board);
  }
  const hour = new Date().getHours();
  const type = hour >= 18 ? 'Sleep' : hour >= 12 ? 'Focus' : 'CBD';
  const pick = strains.find(s=>normalize(s.category).includes(normalize(type))) || dailyShuffle(strains,'dash')[0];
  const recent = recentRecords().length, saved=savedRecords().length, journal=journalRecords().length;
  board.style.cssText = cardStyle(pick);
  board.innerHTML = `<div class="panel-head"><div><span class="eyebrow">Live Wellness Dashboard</span><h3>Your app is learning your pattern</h3></div><button class="small-btn ghost" onclick="showPage('recommend')">Match Now</button></div>
  <button class="live-hero-strip" onclick="openModal('${safeName(pick.name)}')"><img src="${strainImage(pick)}" alt="${pick.name}" onerror="repairStrainImage(this,'${safeName(pick.name)}')"><div><span class="live-pill">${hour>=18?'Tonight':'Right now'}</span><h2>${pick.name}</h2><p>${shortInsight(pick)}</p></div></button>
  <div class="lively-stat-row"><div><strong>${strains.length}</strong><span>Total directions</span></div><div><strong>${Math.max(1, recent)}</strong><span>Viewed</span></div><div><strong>${saved+journal}</strong><span>Saved + journal</span></div></div>
  <div class="quest-carousel"><div class="quest-card done"><span>🌿</span><strong>Explorer</strong><small>${recent} viewed</small><i><em style="width:${Math.min(100,recent/5*100)}%"></em></i></div><div class="quest-card"><span>♡</span><strong>Collector</strong><small>${saved}/3 saved</small><i><em style="width:${Math.min(100,saved/3*100)}%"></em></i></div></div>`;
}
function renderSmartInsights(){
  const box = $('smartInsights'); if(!box) return;
  const recent = recentRecords().map(getStrain).filter(Boolean);
  const top = recent[0] || dailyShuffle(strains,'smart')[0];
  box.innerHTML = `<h2>Smart Recommendations</h2><div class="smart-grid"><div class="smart-card"><span>↻ Recent Behavior</span><h3>You keep exploring ${top.category || 'wellness'} directions</h3><p>Recent views suggest ${(top.time||'balanced').toLowerCase()} profiles may be worth comparing next.</p></div><div class="smart-card"><span>⏰ Time-Based Direction</span><h3>Right now: ${new Date().getHours()<18?'daytime clarity':'evening wind-down'}</h3><p>Use timing, THC sensitivity, and terpene notes before saving or journaling a direction.</p></div></div>`;
}
function renderCategoryRibbons(){
  let rib = $('categoryRibbons'); const home=$('home'); if(!home) return;
  if(!rib){ rib=document.createElement('section'); rib.id='categoryRibbons'; $('smartInsights')?.insertAdjacentElement('afterend', rib); }
  const cats=['CBD','Sleep','Focus','Mood','Stress','Body Comfort','Appetite'];
  rib.innerHTML = `<div class="section-title"><h2>Explore by vibe</h2><p>Swipe through colorful wellness lanes.</p></div><div class="vibe-ribbon">${cats.map(c=>`<button class="vibe-chip" onclick="jumpFilter('${safeName(c)}')"><strong>${c}</strong><small>${(strains.find(s=>normalize(s.category).includes(normalize(c)))||strains[0]).name}</small></button>`).join('')}</div>`;
}
function renderRecentHome(){
  const box = $('recentHome'); if(!box) return;
  const r = recentRecords().map(getStrain).filter(Boolean).slice(0,8);
  box.innerHTML = r.length ? `<div class="recent-carousel">${r.map(s=>`<button class="recent-card" style="${cardStyle(s)}" onclick="openModal('${safeName(s.name)}')"><img src="${strainImage(s)}" alt="${s.name}" onerror="repairStrainImage(this,'${safeName(s.name)}')"><strong>${s.name}</strong><small>${s.category}</small></button>`).join('')}</div>` : `<div class="empty-state">No recently viewed strains yet. Open a profile to start.</div>`;
}
function renderHomeDynamic(){ dailyTip(); renderSpotlight(); renderFeatured(); updateStats(); renderLiveDashboard(); renderSmartInsights(); renderCategoryRibbons(); renderRecentHome(); }

function clearSearch(){ $('searchInput').value=''; renderSearch(); }
function jumpFilter(term){ showPage('search'); $('searchInput').value=term; renderSearch(); }
function renderFilters(){
  const row=$('filterRow'); if(!row) return;
  const filters=['All','CBD','Sleep','Focus','Mood','Stress','Body Comfort','Appetite'];
  row.innerHTML=filters.map(f=>`<button onclick="${f==='All'?`$('searchInput').value='';renderSearch()`:`jumpFilter('${safeName(f)}')`}">${f}</button>`).join('');
}
function renderSearch(){
  renderFilters();
  const q=normalize($('searchInput')?.value || '');
  const filtered = strains.filter(s=>!q || normalize([s.name,s.type,s.category,s.thc,s.cbd,s.time,s.flavor,s.insight,...(s.tags||[]),...(s.goals||[]),...(s.terpenes||[])].join(' ')).includes(q));
  const grid = $('strainGrid');
  if(grid){
    grid.innerHTML = filtered.length ? filtered.map(s=>cardHTML(s)).join('') : `<div class="empty-state">No strain directions matched that search.</div>`;
    grid.setAttribute('data-count', String(filtered.length));
  }
}

function runMatcher(){
  const goal=$('goalSelect').value, sens=$('sensitivitySelect').value, time=$('timeSelect').value, low=$('lowAnxietyToggle').checked;
  let results=strains.map(s=>{
    let score=50;
    if(goal && (s.goals||[]).some(g=>normalize(g).includes(normalize(goal)))) score+=24;
    if(time && normalize(s.time).includes(normalize(time))) score+=15;
    if(low && (normalize(s.thc).includes('low') || normalize(s.cbd).includes('high'))) score+=16;
    if(sens==='low' && normalize(s.thc).includes('high')) score-=18;
    if(sens==='high') score+=5;
    return {...s,_match:Math.max(20,Math.min(99,score))};
  }).sort((a,b)=>b._match-a._match).slice(0,6);
  store('srMatched',[{date:new Date().toISOString(),goal,sens,time,low},...read('srMatched',[]).slice(0,9)]);
  $('matchExplain').classList.remove('hidden');
  $('matchExplain').innerHTML = `<strong>Educational match direction</strong><p>These results compare your goal, timing, THC sensitivity, tags, and terpene notes. This is not medical advice.</p>`;
  $('matchResults').innerHTML = results.map(s=>`<article class="strain-card" style="${cardStyle(s)}" onclick="openModal('${safeName(s.name)}')"><div class="card-hero"><img src="${strainImage(s)}" onerror="repairStrainImage(this,'${safeName(s.name)}')"><span>${s._match}% match</span></div><h3>${s.name}</h3><p>${shortInsight(s)}</p><div class="tags">${(s.tags||[]).slice(0,3).map(t=>`<span class="tag">${t}</span>`).join('')}</div></article>`).join('');
}

function saveFavorite(name){
  const s=getStrain(name); if(!s) return;
  const list=savedRecords().filter(x=>x.name!==s.name);
  store('srSaved',[{name:s.name,date:new Date().toISOString()},...list]);
  toast(`${s.name} saved`); updateStats(); renderSaved();
}
function clearSaved(){ store('srSaved',[]); renderSaved(); updateStats(); }
function clearJournal(){ store('srJournal',[]); renderSaved(); updateStats(); }
function renderSaved(){
  const saved=savedRecords().map(x=>getStrain(x.name)).filter(Boolean);
  const list=$('savedList'); if(list) list.innerHTML=saved.length ? saved.map(s=>`<button class="mini-item" onclick="openModal('${safeName(s.name)}')"><strong>${s.name}</strong><small>${s.category} • ${(s.terpenes||[])[0]||'terpene'}</small></button>`).join('') : `<div class="empty-state">No saved strains yet.</div>`;
  const sel=$('journalStrain'); if(sel) sel.innerHTML = strains.map(s=>`<option value="${s.name}">${s.name}</option>`).join('');
  const journals=journalRecords(); const jl=$('journalList'); if(jl) jl.innerHTML=journals.length ? journals.map(j=>`<div class="mini-item"><strong>${j.strain} — ${j.mood||'Note'}</strong><small>${new Date(j.date).toLocaleDateString()}</small><p>${j.note||''}</p></div>`).join('') : `<div class="empty-state">No journal entries yet.</div>`;
  const chart=$('journalChart'); if(chart) chart.innerHTML = `<strong>${journals.length}</strong><span> entries saved on this device</span>`;
  updateStats();
}
function saveJournal(){
  const entry={strain:$('journalStrain').value,mood:$('journalMood').value,note:$('journalNote').value,date:new Date().toISOString()};
  store('srJournal',[entry,...journalRecords()].slice(0,50));
  $('journalNote').value=''; toast('Journal entry saved'); renderSaved(); updateStats();
}
function initMoodChips(){
  const row=$('journalMoodChips'); if(!row) return;
  ['Calm','Relaxed','Sleepy','Focused','Clear-headed','Too intense'].forEach(m=>{ const b=document.createElement('button'); b.type='button'; b.textContent=m; b.onclick=()=>$('journalMood').value=m; row.appendChild(b); });
}

function renderEducation(){
  const terpeneData = [
    {name:'Myrcene', vibe:'earthy, herbal, musky', direction:'Often associated with calm, evening, and body-comfort style profiles.', examples:['Granddaddy Purple','Northern Lights','Blue Dream','Harlequin']},
    {name:'Limonene', vibe:'citrus, lemon, bright', direction:'Often compared for mood, daytime clarity, and brighter aroma profiles.', examples:['Sour Diesel','Lemon Haze','Gelato','Wedding Cake']},
    {name:'Pinene', vibe:'pine, forest, crisp', direction:'Often discussed for clear-headed, daytime, and fresh aroma directions.', examples:['Jack Herer','Harlequin','Blue Dream','Maui Wowie']},
    {name:'Caryophyllene', vibe:'pepper, spice, clove', direction:'Often associated with grounding, stress-comparison, and body-comfort profiles.', examples:['Girl Scout Cookies','Wedding Cake','Sour Diesel','Cannatonic']},
    {name:'Linalool', vibe:'floral, lavender, soft', direction:'Often discussed for gentle calm, evening, and low-intensity wellness education.', examples:['LA Confidential','Blue Cookies','Godfather OG','Lavender']},
    {name:'Humulene', vibe:'hoppy, earthy, woody', direction:'Often compared in appetite-aware, grounding, and balanced hybrid profiles.', examples:['Girl Scout Cookies','Charlotte\'s Web','Black Cherry Gelato','Pink Runtz']},
    {name:'Terpinolene', vibe:'fresh, herbal, sweet', direction:'Often associated with bright, active, creative, or daytime-style strain education.', examples:['Jack Herer','Durban Poison','Cherry AK','Canna-Tsu']},
    {name:'Ocimene', vibe:'sweet, herbal, tropical', direction:'Often discussed in lighter, brighter, aroma-forward daytime profiles.', examples:['Durban Poison','Marshmallow OG','Zoap','Cherry AK']}
  ];
  $('onboardingSlides').innerHTML = `<h3>How StrainRelief works</h3><p>Compare cannabis wellness directions by goal, timing, THC sensitivity, terpene notes, saved favorites, and journal patterns. This is educational only.</p>`;
  $('terpeneExplorer').innerHTML = `<h3>Terpene Explorer</h3><p class="muted-copy">Tap example strains from each terpene family to compare profiles. Terpenes are aroma compounds often discussed in cannabis education, but effects vary by person, product, dose, and lab results.</p><div class="terpene-grid">${terpeneData.map(t=>`<article class="terpene-card"><span>${t.name}</span><h4>${t.vibe}</h4><p>${t.direction}</p><div class="example-strains">${t.examples.map(ex=>`<button type="button" onclick="openModal('${safeName(ex)}')">${ex}</button>`).join('')}</div></article>`).join('')}</div>`;
  $('locatorBox').innerHTML = `<h3>Dispensary Checklist</h3><ul class="clean-list"><li>Ask for current lab results and terpene percentages.</li><li>Compare THC/CBD levels before buying.</li><li>Start low, especially with high-THC products.</li><li>Follow local laws and do not drive while impaired.</li></ul>`;
  $('termsBox').innerHTML = `<h3>Safety Disclaimer</h3><p>Educational only. Cannabis affects everyone differently. StrainRelief does not diagnose, treat, cure, or prevent any condition. Talk with a licensed professional when needed.</p>`;
  $('learnGrid').innerHTML = education.map(e=>`<article class="education-card"><h3>${e.title}</h3><p>${e.body}</p></article>`).join('');
}

function addRecent(name){
  const s=getStrain(name); if(!s) return;
  const list=recentRecords().filter(n=>n!==s.name);
  store('srRecent',[s.name,...list].slice(0,10));
}
function openModal(name){
  const s=getStrain(name); if(!s) return;
  addRecent(s.name);
  const related=strains.filter(x=>x.name!==s.name && (x.category===s.category || (x.goals||[]).some(g=>(s.goals||[]).includes(g)))).slice(0,3);
  $('modalBody').innerHTML = `<div class="modal-hero" style="${cardStyle(s)}"><img src="${strainImage(s)}" alt="${s.name}" onerror="repairStrainImage(this,'${safeName(s.name)}')"><span>${s.category}</span></div><h2>${s.name}</h2><p>${s.insight || matchSummary(s)}</p><div class="detail-grid"><div><strong>THC</strong><span>${s.thc}</span></div><div><strong>CBD</strong><span>${s.cbd}</span></div><div><strong>Time</strong><span>${s.time}</span></div><div><strong>Flavor</strong><span>${s.flavor}</span></div></div><h3>Terpenes</h3><div class="tags">${(s.terpenes||[]).map(t=>`<span class="tag">${t}</span>`).join('')}</div><h3>Good to compare for</h3><div class="tags">${(s.goals||[]).map(t=>`<span class="tag">${t}</span>`).join('')}</div><p class="safety-note">Educational only. Cannabis affects everyone differently. Follow local laws and do not drive while impaired.</p><div class="modal-actions"><button onclick="saveFavorite('${safeName(s.name)}')">Save</button><button class="ghost" onclick="showPage('recommend');closeModal();">Match</button></div><h3>Similar directions</h3><div class="similar-row">${related.map(r=>`<button onclick="openModal('${safeName(r.name)}')">${r.name}</button>`).join('')}</div>`;
  $('strainModal').classList.remove('hidden');
  document.body.classList.add('modal-open');
  renderRecentHome(); updateStats();
}
function closeModal(){ $('strainModal').classList.add('hidden'); document.body.classList.remove('modal-open'); }
function toast(msg){ const t=$('toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(window.__toastTimer); window.__toastTimer=setTimeout(()=>t.classList.remove('show'),2200); }
function surpriseMe(){ const s=dailyShuffle(strains, 'surprise'+Date.now())[0]; openModal(s.name); }
function openCompare(){ showPage('recommend'); }
function clearCompare(){ $('compareTray')?.classList.add('hidden'); }

window.repairStrainImage=repairStrainImage; window.openModal=openModal; window.closeModal=closeModal; window.surpriseMe=surpriseMe; window.jumpFilter=jumpFilter; window.clearSearch=clearSearch; window.runMatcher=runMatcher; window.saveJournal=saveJournal; window.clearJournal=clearJournal; window.clearSaved=clearSaved; window.saveFavorite=saveFavorite; window.openCompare=openCompare; window.clearCompare=clearCompare;

function boot(){
  document.documentElement.classList.add('app-ready');
  document.body.classList.add('app-ready');
  document.body.classList.remove('modal-open');
  document.documentElement.style.overflowY = 'auto';
  document.body.style.overflowY = 'auto';
  if(localStorage.getItem('srSafetyAccepted')!=='yes'){ $('safetyGate')?.classList.remove('hidden'); }
  $('acceptSafetyBtn')?.addEventListener('click',()=>{ localStorage.setItem('srSafetyAccepted','yes'); $('safetyGate')?.classList.add('hidden'); });
  $('searchInput')?.addEventListener('input',renderSearch);
  $('savedSearch')?.addEventListener('input',renderSaved);
  initMoodChips(); renderHomeDynamic(); renderSearch(); renderSaved(); renderEducation();
  if('serviceWorker' in navigator) navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', boot); else boot();
